// colonna destra: nome editabile (etichetta `name` di Spatie Media
// + rename del file fisico, così download/zip restano coerenti —
// salvataggio live al blur, niente submit del form)
Group::make([
    TextInput::make('name')
        ->label(__('digital-hub::assets.display_name'))
        ->default($media->name)
        ->required()
        ->maxLength(255)
        ->live(onBlur: true)
        ->afterStateUpdated(function (?string $state) use ($media): void {
            if (! is_string($state) || $state === '' || $state === $media->name) {
                return;
            }

            $media->name = $state;
            // il file fisico segue l'etichetta (estensione preservata):
            // cambiando `file_name`, l'observer di spatie rinomina il
            // file su disco al salvataggio (`syncFileNames`)
            $media->file_name = AssetFileName::fromDisplayName($state, (string) $media->file_name);
            $media->save();

            Notification::make()->success()->title(__('digital-hub::assets.name_updated'))->send();
        }),
]),

