23	/**
24	 * Sostituzione del file fisico di un asset (digital-hub 22i): il record Media
25	 * mantiene lo stesso id (dati e relazioni preservati), cambia solo il file e
26	 * i suoi attributi; metadati/anteprima azzerati e job rielaborazione in coda.
27	 */
28	class AssetFileReplaceTest extends TestCase
29	{
30	    use RefreshDatabase;
31	
32	    public function test_replace_keeps_id_updates_file_and_requeues_processing(): void
33	    {
34	        Storage::fake('assets');
35	        Queue::fake();
36	
37	        $product = Product::create(['name' => ['it' => 'Tavolo']]);
38	        $media = $product
39	            ->addMediaFromString('vecchio contenuto')
40	            ->usingFileName('old.txt')
41	            ->toMediaCollection('assets');
42	
43	        // simula un asset già elaborato: metadati estratti + poster generato
44	        ExtractedMetadata::write($media, ['common' => ['size' => 17]]);
45	        $disk = Storage::disk('assets');
46	        $disk->put(AssetPreview::relativePath($media), 'poster');
47	        $media->setCustomProperty(AssetPreview::PROPERTY, AssetPreview::relativePath($media));
48	        $media->setAttribute('processing_status', AssetProcessingStatus::Completed->value);
49	        $media->save();
50	
51	        $originalId = $media->getKey();
52	        $oldPath = $media->getPathRelativeToRoot();
53	
54	        AssetFileReplacer::replace($media, UploadedFile::fake()->createWithContent('nuovo file.pdf', '%PDF-1.4 nuovo'));
55	
56	        // stesso record, attributi del nuovo file (nome sanitizzato come spatie)
57	        $media->refresh();
58	        $this->assertSame($originalId, $media->getKey());
59	        $this->assertSame('nuovo-file.pdf', $media->file_name);
60	        $this->assertSame(strlen('%PDF-1.4 nuovo'), $media->size);
61	
62	        // file fisico: il nuovo esiste, il vecchio e il poster sono stati rimossi
63	        $disk->assertExists($media->getPathRelativeToRoot());
64	        $disk->assertMissing($oldPath);
65	        $disk->assertMissing(AssetPreview::relativePath($media));
66	        $this->assertSame('%PDF-1.4 nuovo', $disk->get($media->getPathRelativeToRoot()));
67	
68	        // stato azzerato + job in coda
69	        $this->assertSame([], ExtractedMetadata::forMedia($media));
70	        $this->assertNull($media->getCustomProperty(AssetPreview::PROPERTY));
71	        $this->assertSame(AssetProcessingStatus::Pending->value, $media->getAttribute('processing_status'));
72	        Queue::assertPushed(ProcessAssetJob::class, fn (ProcessAssetJob $job): bool => $job->mediaId === $originalId);
73	    }
