public function test_replace_realigns_a_previously_renamed_label_to_the_new_file(): void
{
    Storage::fake('assets');
    Queue::fake();

    $product = Product::create(['name' => ['it' => 'Tavolo']]);
    $media = $product
        ->addMediaFromString('vecchio')
        ->usingFileName('catalogo-2026.pdf')
        ->toMediaCollection('assets');

    // etichetta curata a mano dallo slideover (14d)
    $media->name = 'Catalogo 2026';
    $media->save();

    AssetFileReplacer::replace($media, UploadedFile::fake()->createWithContent('catalogo-2027.pdf', 'nuovo'));

    // il contenuto è cambiato: tenere "Catalogo 2026" sul file 2027 sarebbe
    // fuorviante, e lascerebbe `name` e `file_name` disallineati
    $media->refresh();
    $this->assertSame('catalogo-2027', $media->name);
    $this->assertSame('catalogo-2027.pdf', $media->file_name);
}

